// Maintainer script: builds public/vendor/codemirror.js (minified IIFE that
// defines window.HubEditor) and public/vendor/codemirror.LICENSE.txt.
//
//   cd scripts/vendor && npm ci && node build-codemirror.mjs
//
// The app itself never runs this; the built files are committed.

import { build } from 'esbuild';
import { readFile, readdir, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { gzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '..', '..');
const outDir = path.join(repoRoot, 'public', 'vendor');
const outFile = path.join(outDir, 'codemirror.js');
const licenseFile = path.join(outDir, 'codemirror.LICENSE.txt');

// Anything else fails the build: the Hub ships permissive licences only.
const ALLOWED_LICENSES = new Set(['MIT', 'ISC', 'BSD-2-Clause', 'BSD-3-Clause', '0BSD']);

const result = await build({
  absWorkingDir: here,
  entryPoints: ['codemirror-entry.mjs'],
  outfile: outFile,
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['es2020'],
  minify: true,
  charset: 'ascii',
  legalComments: 'none', // licence texts go to codemirror.LICENSE.txt
  sourcemap: false,
  metafile: true,
  write: false,
  logLevel: 'warning',
  banner: {
    js: '/* SchulHub: CodeMirror 6 bundle, defines window.HubEditor. Generated by scripts/vendor/build-codemirror.mjs - do not edit. Licences: codemirror.LICENSE.txt */',
  },
});

// ---------- Which packages ended up in the bundle ----------

function packageDirOf(input) {
  const parts = input.split('/');
  const at = parts.lastIndexOf('node_modules');
  if (at < 0) return null; // our own entry file
  const len = parts[at + 1].startsWith('@') ? 2 : 1;
  return parts.slice(0, at + 1 + len).join('/');
}

const output = result.metafile.outputs[path.relative(here, outFile)];
const bytesByPackage = new Map();
for (const [input, info] of Object.entries(output.inputs)) {
  const dir = packageDirOf(input) || '(entry)';
  bytesByPackage.set(dir, (bytesByPackage.get(dir) || 0) + info.bytesInOutput);
}

async function findLicenseFile(dir) {
  const names = await readdir(dir);
  const match = names.filter((n) => /^(licen[cs]e|copying)(\.(md|txt))?$/i.test(n)).sort();
  return match.length ? path.join(dir, match[0]) : null;
}

const packages = [];
for (const dir of bytesByPackage.keys()) {
  if (dir === '(entry)') continue;
  const abs = path.join(here, dir);
  const pkg = JSON.parse(await readFile(path.join(abs, 'package.json'), 'utf8'));
  const license = typeof pkg.license === 'string' ? pkg.license : '';
  if (!ALLOWED_LICENSES.has(license)) {
    throw new Error(`${pkg.name}@${pkg.version}: licence "${license}" is not on the allow list`);
  }
  const file = await findLicenseFile(abs);
  if (!file) throw new Error(`${pkg.name}@${pkg.version}: no LICENSE file found in ${dir}`);
  const repo = typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url || '';
  packages.push({
    name: pkg.name,
    version: pkg.version,
    license,
    repo: repo.replace(/^git\+/, '').replace(/\.git$/, ''),
    text: (await readFile(file, 'utf8')).replace(/\r\n/g, '\n').trim(),
    bytes: bytesByPackage.get(dir),
  });
}
packages.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

// ---------- Write files ----------

const rule = '='.repeat(72);
const licenseText = [
  'Third-party software bundled in public/vendor/codemirror.js',
  'Generated by scripts/vendor/build-codemirror.mjs - do not edit.',
  '',
  ...packages.map((p) => `  ${p.name} ${p.version} (${p.license})`),
  '',
  ...packages.flatMap((p) => [
    rule,
    `${p.name} ${p.version}`,
    `License: ${p.license}`,
    ...(p.repo ? [`Source: ${p.repo}`] : []),
    rule,
    '',
    p.text,
    '',
  ]),
].join('\n');

const js = result.outputFiles[0].contents;
await mkdir(outDir, { recursive: true });
await writeFile(outFile, js);
await writeFile(licenseFile, licenseText + '\n');

// ---------- Report ----------

const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
console.log(`${path.relative(repoRoot, outFile)}: ${kb(js.length)} (gzip ${kb(gzipSync(js).length)}), sha256 ${createHash('sha256').update(js).digest('hex').slice(0, 16)}`);
console.log(`${path.relative(repoRoot, licenseFile)}: ${packages.length} packages`);
console.log('Largest contributors (minified bytes):');
for (const [dir, bytes] of [...bytesByPackage].sort((a, b) => b[1] - a[1]).slice(0, 10)) {
  console.log(`  ${kb(bytes).padStart(9)}  ${dir.replace(/^node_modules\//, '')}`);
}
